#include <stdio.h>

typedef long long ll;

typedef struct {
    ll x, y;
} Point;

ll cross(Point a, Point b) {
    return a.x * b.y - a.y * b.x;
}

int main(void) {
    Point p[7];

    for (int i = 0; i < 7; i++) {
        if (scanf("%lld %lld", &p[i].x, &p[i].y) != 2) return 0;
    }

    Point v12 = {p[1].x - p[0].x, p[1].y - p[0].y};
    Point v13 = {p[2].x - p[0].x, p[2].y - p[0].y};
    Point base = {p[2].x - p[1].x, p[2].y - p[1].y};

    ll dot = v12.x * v13.x + v12.y * v13.y;
    ll len12 = v12.x * v12.x + v12.y * v12.y;
    ll len13 = v13.x * v13.x + v13.y * v13.y;

    int valid = dot > 0 && len12 == len13;

    for (int i = 3; i <= 4; i++) {
        Point v = {p[i].x - p[1].x, p[i].y - p[1].y};
        if (cross(base, v) != 0) valid = 0;
    }

    if (p[1].x + p[2].x != p[3].x + p[4].x ||
        p[1].y + p[2].y != p[3].y + p[4].y) {
        valid = 0;
    }

    ll baseLen = base.x * base.x + base.y * base.y;
    Point v45 = {p[4].x - p[3].x, p[4].y - p[3].y};
    ll len45 = v45.x * v45.x + v45.y * v45.y;
    if (baseLen <= len45) valid = 0;

    Point v46 = {p[5].x - p[3].x, p[5].y - p[3].y};
    Point v57 = {p[6].x - p[4].x, p[6].y - p[4].y};
    if (base.x * v46.x + base.y * v46.y != 0 ||
        base.x * v57.x + base.y * v57.y != 0) {
        valid = 0;
    }

    ll len46 = v46.x * v46.x + v46.y * v46.y;
    ll len57 = v57.x * v57.x + v57.y * v57.y;
    if (len46 != len57) valid = 0;

    Point v1 = {p[0].x - p[1].x, p[0].y - p[1].y};
    Point v6 = {p[5].x - p[1].x, p[5].y - p[1].y};
    ll side1 = cross(base, v1);
    ll side6 = cross(base, v6);
    if (!((side1 < 0 && side6 > 0) || (side1 > 0 && side6 < 0))) {
        valid = 0;
    }

    printf("%c\n", valid ? 'S' : 'N');
    return 0;
}
